:host {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #0066cc;
  --warm: #ff6b35;
  --line: #e0e0e0;
  --paper: #fafafa;
}

.chapter-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--paper);
  padding: 24px;
  max-width: 900px;
  margin: 0 auto;
}

.chapter-header {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 16px;
  margin-bottom: 32px;
}

.chapter-title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 8px 0;
  color: var(--ink);
}

.chapter-takeaway {
  font-size: 15px;
  color: var(--muted);
  margin: 0;
  line-height: 1.5;
}

.content-block {
  margin-bottom: 40px;
}

.section-title {
  font-size: 22px;
  font-weight: 600;
  margin: 0 0 20px 0;
  color: var(--ink);
  border-left: 4px solid var(--accent);
  padding-left: 12px;
}

.evidence-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 20px;
}

@media (max-width: 600px) {
  .evidence-grid {
    grid-template-columns: 1fr;
  }
}

.evidence-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 16px;
}

.card-title {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 12px 0;
  color: var(--accent);
}

.card-text {
  font-size: 15px;
  color: var(--ink);
  margin: 0 0 12px 0;
  line-height: 1.5;
}

.source-btn {
  font-size: 13px;
  padding: 6px 12px;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.2s;
}

.source-btn:hover {
  background: #0052a3;
}

.source-group {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.key-claim {
  background: #f0f7ff;
  border-left: 4px solid var(--accent);
  padding: 16px;
  margin-top: 20px;
}

.claim-text {
  font-size: 15px;
  margin: 0;
  color: var(--ink);
}

.interaction-panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 20px;
}

.step-controls {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.step-btn {
  font-size: 14px;
  padding: 10px 16px;
  background: #f5f5f5;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.2s;
}

.step-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.step-btn:hover:not(.active) {
  background: #e8e8e8;
}

.step-content {
  min-height: 200px;
}

.step-panel {
  display: none;
}

.step-panel.active {
  display: block;
}

.step-title {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 12px 0;
  color: var(--ink);
}

.step-text {
  font-size: 15px;
  color: var(--ink);
  margin: 0 0 16px 0;
  line-height: 1.5;
}

.improvement-list {
  font-size: 15px;
  color: var(--ink);
  margin: 0 0 16px 0;
  padding-left: 20px;
}

.improvement-list li {
  margin-bottom: 8px;
  line-height: 1.5;
}

.limitation-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-top: 16px;
}

@media (max-width: 600px) {
  .limitation-grid {
    grid-template-columns: 1fr;
  }
}

.limitation-item {
  background: #fff5f0;
  border: 1px solid #ffccbc;
  border-radius: 4px;
  padding: 16px;
}

.limitation-item.critical {
  border-left: 4px solid var(--warm);
}

.limit-icon {
  font-size: 24px;
  margin-bottom: 8px;
}

.limit-title {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 8px 0;
  color: var(--ink);
}

.limit-desc {
  font-size: 14px;
  color: var(--ink);
  margin: 0;
  line-height: 1.5;
}

.acceptance-check {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.check-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--muted);
  margin: 0 0 12px 0;
}

.check-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.check-item {
  font-size: 15px;
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: 8px;
}

.check-mark {
  font-size: 16px;
  color: var(--muted);
}

.check-item[data-checked="true"] .check-mark {
  color: #4caf50;
}

.check-item[data-checked="true"] .check-text {
  text-decoration: line-through;
  color: var(--muted);
}

