(function() {
  'use strict';

  const chapterContainer = document.getElementById('ch1-problem');
  if (!chapterContainer) return;

  const paperMindData = window.paperMindData || { sources: {}, nodes: [] };

  const stepButtons = chapterContainer.querySelectorAll('.step-btn');
  const stepPanels = chapterContainer.querySelectorAll('.step-panel');
  const checkItems = chapterContainer.querySelectorAll('.check-item');
  const sourceButtons = chapterContainer.querySelectorAll('.source-btn');

  function activateStep(stepIndex) {
    stepButtons.forEach((btn, idx) => {
      btn.classList.toggle('active', idx === stepIndex);
    });
    stepPanels.forEach((panel, idx) => {
      panel.classList.toggle('active', idx === stepIndex);
    });

    if (stepIndex === 2) {
      checkItems.forEach(item => {
        item.setAttribute('data-checked', 'true');
      });
    } else {
      checkItems.forEach(item => {
        item.setAttribute('data-checked', 'false');
      });
    }
  }

  stepButtons.forEach((btn, idx) => {
    btn.addEventListener('click', () => {
      activateStep(idx);
    });
  });

  sourceButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const sourceId = btn.getAttribute('data-source');
      if (paperMindData.sources && paperMindData.sources[sourceId]) {
        const source = paperMindData.sources[sourceId];
        const event = new CustomEvent('paperMind:source:view', {
          detail: { sourceId, source },
          bubbles: true
        });
        btn.dispatchEvent(event);
      }
    });
  });

  const resetBtn = document.createElement('button');
  resetBtn.type = 'button';
  resetBtn.className = 'step-btn';
  resetBtn.textContent = '复位';
  resetBtn.style.marginTop = '16px';
  resetBtn.addEventListener('click', () => {
    activateStep(0);
  });

  const interactionPanel = chapterContainer.querySelector('.interaction-panel');
  if (interactionPanel) {
    interactionPanel.appendChild(resetBtn);
  }

  activateStep(0);

  const observer = new MutationObserver(() => {
    const currentActive = chapterContainer.querySelector('.step-panel.active');
    if (currentActive) {
      const stepIndex = Array.from(stepPanels).indexOf(currentActive);
      if (stepIndex === 2) {
        checkItems.forEach(item => {
          item.setAttribute('data-checked', 'true');
        });
      }
    }
  });

  observer.observe(chapterContainer, { childList: true, subtree: true });

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reducedMotion) {
    const style = document.createElement('style');
    style.textContent = '* { transition: none !important; animation: none !important; }';
    chapterContainer.appendChild(style);
  }
})();
